"""Every rounding rule of meterbill lives here."""

from __future__ import annotations

import math
from decimal import Decimal
from fractions import Fraction

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _check(value, step, method) -> None:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be a positive decimal")
    if not value.is_finite():
        raise ValueError("value must be finite")


def _units(ratio: Fraction, method: str) -> int:
    """Round a non-negative ratio to an integer."""
    q, r = divmod(ratio.numerator, ratio.denominator)
    if method == DOWN:
        return q
    twice = 2 * r
    if twice > ratio.denominator:
        return q + 1
    if twice < ratio.denominator:
        return q
    if method == HALF_UP:
        return q + 1
    return q + (q & 1)


def _build(negative: bool, count: int, step: Decimal) -> Decimal:
    """`count` steps, carrying the exponent of `step` (and the sign, zero included)."""
    _, digits, exp = step.as_tuple()
    coefficient = int("".join(map(str, digits)))
    n = count * coefficient
    return Decimal((1 if negative else 0, tuple(int(c) for c in str(n)), exp))


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    _check(value, step, method)
    n = _units(abs(Fraction(value)) / Fraction(step), method)
    return _build(value.is_signed(), n, step)


def allocate(amounts: list, step: Decimal) -> list:
    if not isinstance(step, Decimal):
        raise TypeError("step must be Decimal")
    amounts = list(amounts)
    for a in amounts:
        _check(a, step, HALF_UP)
    exact = [Fraction(a) for a in amounts]
    fstep = Fraction(step)
    # signed counts of steps
    def count(ratio: Fraction, method: str) -> int:
        n = _units(abs(ratio), method)
        return -n if ratio < 0 else n

    parts = [count(f / fstep, DOWN) for f in exact]
    whole = count(sum(exact, Fraction(0)) / fstep, HALF_UP)
    rest = whole - sum(parts)
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] += rest
            break
    return [_build(False, abs(n), step).copy_negate() if n < 0 else _build(False, n, step) for n in parts]


def legacy_cents(value: float, places: int = 2) -> float:
    scale = 10 ** places
    return math.floor(value * scale + 0.5) / scale


def fixed(value, places: int, method: str = HALF_EVEN) -> str:
    if isinstance(places, bool) or not isinstance(places, int) or places < 0:
        raise ValueError("places must be a non-negative integer")
    if isinstance(value, float):
        if method != HALF_EVEN:
            raise ValueError("a float can only be written half to even")
        return format(value, "." + str(places) + "f")
    if not isinstance(value, Decimal):
        raise TypeError("value must be a float or a Decimal")
    step = Decimal((0, (1,), -places))
    return format(round_amount(value, step, method), "f")
